import React, { useState, useEffect } from 'react';
import { XCircle } from 'lucide-react';
import './App.css';

function App() {
  const [amount, setAmount] = useState(2000);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [fundraisingData, setFundraisingData] = useState({
    currentAmount: 0,
    goalAmount: 45000,
    topContributors: [],
    recentSupporters: []
  });
  const [liveDonation, setLiveDonation] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  // Predefined amount options
  const amountOptions = [500, 1000, 2000, 5000];

  // Fetch initial data
  useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);
        const response = await fetch('/api/fundraising-data');
        const data = await response.json();
        setFundraisingData(data);
        setIsLoading(false);
      } catch (error) {
        console.error('Error fetching fundraising data:', error);
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  // Set up WebSocket connection for live updates
  useEffect(() => {
    // In a real application, you would use a real WebSocket connection
    // For demonstration, we'll use a simulated WebSocket with setInterval
    const simulatedSocket = setInterval(() => {
      // Simulate receiving a donation 30% of the time
      if (Math.random() < 0.3) {
        const names = ['Rahul Joshi', 'Meera Shah', 'Anand Patel', 'Kavita Desai', 'Vijay Singh'];
        const amounts = [500, 1000, 1500, 2000, 3000, 5000];

        const randomName = names[Math.floor(Math.random() * names.length)];
        const randomAmount = amounts[Math.floor(Math.random() * amounts.length)];

        // Update live donation state
        setLiveDonation({
          name: randomName,
          amount: randomAmount,
          timestamp: new Date()
        });

        // Update data
        fetchUpdatedData();

        // Hide notification after 5 seconds
        setTimeout(() => setLiveDonation(null), 5000);
      }
    }, 30000); // Check every 30 seconds

    return () => clearInterval(simulatedSocket);
  }, []);

  // Fetch updated data
  const fetchUpdatedData = async () => {
    try {
      const response = await fetch('/api/fundraising-data');
      const data = await response.json();
      setFundraisingData(data);
    } catch (error) {
      console.error('Error fetching updated data:', error);
    }
  };

  // Handle payment
  const handlePayment = async (e) => {
    e.preventDefault();

    if (!amount || !name || !email) {
      alert('Please fill in all required fields.');
      return;
    }

    try {
      // Create order
      const orderResponse = await fetch('/api/create-order', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          amount: amount * 100, // Convert to paisa
          name,
          email,
          message
        }),
      });

      const orderData = await orderResponse.json();

      if (orderData.error) {
        alert('Error creating order: ' + orderData.error);
        return;
      }

      // Initialize Razorpay
      const options = {
        key: "rzp_test_bv3a3THqFsS1Y9",
        amount: amount * 100,
        currency: "INR",
        name: "GT Bike Fundraiser",
        description: "Contribution to GT Bike fundraising campaign",
        order_id: orderData.id,
        handler: async function(response) {
          // Verify payment
          const verifyResponse = await fetch('/api/verify-payment', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              razorpay_order_id: response.razorpay_order_id,
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_signature: response.razorpay_signature,
              amount,
              name,
              email,
              message
            }),
          });

          const verifyData = await verifyResponse.json();

          if (verifyData.success) {
            alert("Thank you for your contribution!");
            setName('');
            setEmail('');
            setMessage('');
            fetchUpdatedData();
          } else {
            alert("Payment verification failed. Please try again.");
          }
        },
        prefill: {
          name,
          email
        },
        theme: {
          color: "#1a73e8"
        }
      };

      const razorpay = new window.Razorpay(options);
      razorpay.open();

    } catch (error) {
      console.error('Payment error:', error);
      alert('There was an error processing your payment. Please try again.');
    }
  };

  // Calculate progress percentage
  const progressPercentage = Math.min((fundraisingData.currentAmount / fundraisingData.goalAmount) * 100, 100);

  return (
    <div className="bg-gray-50 min-h-screen pb-12">
      {/* Header */}
      <header className="bg-blue-600 text-white text-center py-12 px-4">
        <h1 className="text-4xl font-bold mb-2">Help Me Get My Dream GT Bike!</h1>
        <p className="text-xl">Support my goal and be a part of this journey</p>
      </header>

      <main className="max-w-6xl mx-auto px-4 mt-8">
        <div className="flex flex-col lg:flex-row gap-8">
          {/* Main Content */}
          <div className="flex-grow bg-white rounded-lg shadow-md p-6">
            <img 
              src="/api/placeholder/600/350" 
              alt="GT Bike" 
              className="w-full max-w-lg mx-auto rounded-lg mb-6" 
            />

            <h2 className="text-2xl font-bold mb-4">My Bike Dream</h2>
            <p className="mb-4">
              Hi everyone! I've been dreaming about getting a GT Bike for a long time now. 
              GT Bikes are known for their quality, performance, and durability, making them 
              perfect for both casual riding and more intense adventures.
            </p>
            <p className="mb-6">
              With your support, I can finally make this dream a reality. Every contribution, 
              no matter how small, gets me closer to my goal.
            </p>

            {/* Progress Bar */}
            <div className="mb-8">
              <h3 className="text-xl font-semibold mb-3">Fundraising Progress</h3>
              <div className="h-6 bg-gray-200 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-green-500 rounded-full transition-all duration-700 ease-out"
                  style={{ width: `${progressPercentage}%` }}
                ></div>
              </div>
              <div className="flex justify-between mt-2 font-bold">
                <span>₹{fundraisingData.currentAmount.toLocaleString()} raised</span>
                <span>Goal: ₹{fundraisingData.goalAmount.toLocaleString()}</span>
              </div>
            </div>

            {/* Top Contributors */}
            <div className="bg-blue-50 rounded-lg p-6 mb-8">
              <h3 className="text-xl font-semibold text-center text-blue-600 mb-4">
                Top 5 Contributors
              </h3>

              {isLoading ? (
                <div className="text-center py-4">Loading top contributors...</div>
              ) : (
                <div>
                  {fundraisingData.topContributors.map((contributor, index) => (
                    <div key={index} className="flex items-center bg-white p-3 rounded-lg mb-3 shadow-sm">
                      <div className="text-2xl font-bold text-blue-600 mr-4 w-8">
                        #{index + 1}
                      </div>
                      <div className="flex-grow">
                        <div className="font-semibold flex items-center">
                          {contributor.name}
                          {index === 0 && (
                            <span className="ml-2 bg-yellow-300 text-yellow-800 text-xs px-2 py-1 rounded-full">
                              Top Donor
                            </span>
                          )}
                        </div>
                        <div className="text-green-600 font-semibold">
                          ₹{contributor.amount.toLocaleString()}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <h3 className="text-xl font-semibold mb-3">Why This Bike?</h3>
            <p className="mb-6">
              GT Bikes are renowned for their innovative designs and high-quality components. 
              The specific model I'm eyeing has the perfect balance of performance and comfort, 
              allowing me to explore new trails and enjoy longer rides without fatigue.
            </p>

            {/* Updates */}
            <div className="mt-8">
              <h3 className="text-xl font-semibold mb-4">Campaign Updates</h3>

              <div className="border-l-4 border-blue-500 bg-gray-50 p-4 mb-4">
                <h4 className="font-bold">Halfway to the goal!</h4>
                <p className="text-gray-600 text-sm mb-2">May 1, 2025</p>
                <p>
                  We're making amazing progress! Thanks to all your generous contributions, 
                  we're now {Math.round(progressPercentage)}% of the way to our target. Every donation 
                  brings me closer to hitting the trails with my new GT Bike!
                </p>
              </div>

              <div className="border-l-4 border-blue-500 bg-gray-50 p-4">
                <h4 className="font-bold">Campaign Launched!</h4>
                <p className="text-gray-600 text-sm mb-2">April 25, 2025</p>
                <p>
                  Today marks the beginning of my fundraising journey. I'm excited to share 
                  this goal with all of you and appreciate any support you can offer!
                </p>
              </div>
            </div>
          </div>

          {/* Sidebar */}
          <div className="lg:w-80 space-y-6">
            {/* Donation Form */}
            <div className="bg-white rounded-lg shadow-md p-6">
              <h3 className="text-xl font-semibold mb-4">Make a Contribution</h3>

              <form onSubmit={handlePayment}>
                <div className="mb-4">
                  <label className="block font-medium mb-2">Select Amount</label>
                  <div className="grid grid-cols-2 gap-2 mb-2">
                    {amountOptions.map((option) => (
                      <button
                        key={option}
                        type="button"
                        className={`py-2 px-3 border-2 rounded-md text-center ${
                          amount === option 
                            ? 'border-blue-500 bg-blue-50' 
                            : 'border-gray-300 hover:border-blue-300'
                        }`}
                        onClick={() => setAmount(option)}
                      >
                        ₹{option.toLocaleString()}
                      </button>
                    ))}
                  </div>
                  <input
                    type="number"
                    className="w-full p-3 border border-gray-300 rounded-md"
                    placeholder="Or enter custom amount"
                    value={amount}
                    onChange={(e) => setAmount(Number(e.target.value))}
                    min="100"
                  />
                </div>

                <div className="mb-4">
                  <label className="block font-medium mb-2">Your Name</label>
                  <input
                    type="text"
                    className="w-full p-3 border border-gray-300 rounded-md"
                    placeholder="Enter your name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    required
                  />
                </div>

                <div className="mb-4">
                  <label className="block font-medium mb-2">Email Address</label>
                  <input
                    type="email"
                    className="w-full p-3 border border-gray-300 rounded-md"
                    placeholder="Enter your email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                  />
                </div>

                <div className="mb-4">
                  <label className="block font-medium mb-2">Message (Optional)</label>
                  <input
                    type="text"
                    className="w-full p-3 border border-gray-300 rounded-md"
                    placeholder="Add a short message"
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                  />
                </div>

                <button
                  type="submit"
                  className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-4 rounded-md transition-colors"
                >
                  Contribute Now
                </button>
              </form>
            </div>

            {/* Recent Supporters */}
            <div className="bg-white rounded-lg shadow-md p-6">
              <h3 className="text-xl font-semibold mb-4">Recent Supporters</h3>

              {isLoading ? (
                <div className="text-center py-4">Loading recent supporters...</div>
              ) : (
                <div className="space-y-4">
                  {fundraisingData.recentSupporters.map((supporter, index) => {
                    const initials = supporter.name
                      .split(' ')
                      .map(n => n[0])
                      .join('')
                      .toUpperCase();

                    return (
                      <div key={index} className="flex items-center pb-3 border-b border-gray-200">
                        <div className="w-10 h-10 bg-blue-600 text-white rounded-full flex items-center justify-center font-bold mr-3">
                          {initials}
                        </div>
                        <div>
                          <div className="font-semibold">{supporter.name}</div>
                          <div className="text-green-600 font-semibold">
                            ₹{supporter.amount.toLocaleString()}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      </main>

      {/* Live Donation Alert */}
      {liveDonation && (
        <div className="fixed bottom-4 right-4 bg-white rounded-lg shadow-lg p-4 max-w-xs animate-slide-in">
          <div className="flex justify-between items-start">
            <div className="font-bold text-blue-600 mb-1">New Donation!</div>
            <button 
              onClick={() => setLiveDonation(null)}
              className="text-gray-400 hover:text-gray-600"
            >
              <XCircle size={18} />
            </button>
          </div>
          <p>
            {liveDonation.name} just donated ₹{liveDonation.amount.toLocaleString()}!
          </p>
        </div>
      )}

      <footer className="text-center mt-12 text-gray-500 text-sm">
        <p>This campaign is powered by Razorpay. All transactions are secure.</p>
        <p className="mt-2">© 2025 GT Bike Fundraising Campaign. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default App;
